package com.lamggm.rospocket;
import org.junit.*;import org.json.*;import java.util.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=31)
public class RobotTfTest {
 static JSONObject edge(String parent,String child,long stamp,boolean fixed,double x,double y,double yaw)throws Exception{return new JSONObject().put("parent",parent).put("child",child).put("stamp",stamp).put("static",fixed).put("writer",fixed?"s":"d").put("translation",new JSONArray().put(x).put(y).put(0)).put("rotation",new JSONArray().put(0).put(0).put(Math.sin(yaw/2)).put(Math.cos(yaw/2)));}
 static Set<String> links(){return new LinkedHashSet<>(Arrays.asList("base","wheel","camera"));}
 @Test public void composesNonzeroTransformsAtCommonTimestampAndKeepsStaticEdges()throws Exception{RobotTf tf=new RobotTf();tf.accept(new JSONArray().put(edge("base","wheel",10,false,1,0,Math.PI/2)).put(edge("wheel","camera",0,true,1,0,0)),100);RobotTf.Pose p=tf.solve("base",links(),100);assertTrue(p.status,p.live);assertEquals(10,p.stamp);assertArrayEquals(new double[]{1,1,0},RobotDescription.point(p.transforms.get("camera"),0,0,0),1e-8);tf.accept(new JSONArray().put(edge("base","wheel",20,false,2,0,0)),200);assertEquals(3,tf.solve("base",links(),200).transforms.get("camera")[3],1e-8);}
 @Test public void absentStaleAndRepeatedStampNeverBecomeCurrentFromFreshReceipts()throws Exception{RobotTf tf=new RobotTf();assertFalse(tf.solve("base",links(),0).live);JSONArray rows=new JSONArray().put(edge("base","wheel",10,false,1,0,0)).put(edge("wheel","camera",0,true,0,0,0));tf.accept(rows,100);assertTrue(tf.solve("base",links(),100).live);tf.accept(rows,3000000100L);assertFalse(tf.solve("base",links(),3000000100L).live);tf.accept(new JSONArray().put(edge("base","wheel",11,false,2,0,0)),3000000200L);assertTrue(tf.solve("base",links(),3000000200L).live);}
 @Test public void picksACommonTimeRatherThanMixingNewestSamples()throws Exception{RobotTf tf=new RobotTf();tf.accept(new JSONArray().put(edge("base","wheel",10,false,1,0,0)).put(edge("wheel","camera",10,false,0,1,0)),100);tf.accept(new JSONArray().put(edge("base","wheel",20,false,5,0,0)),200);RobotTf.Pose p=tf.solve("base",links(),200);assertTrue(p.live);assertEquals(10,p.stamp);assertEquals(1,p.transforms.get("camera")[3],0);}
 @Test public void rejectsCyclesConflictingParentsAndInvalidQuaternion()throws Exception{RobotTf tf=new RobotTf();tf.accept(new JSONArray().put(edge("camera","wheel",1,false,0,0,0)).put(edge("wheel","camera",1,false,0,0,0)),100);assertFalse(tf.solve("base",links(),100).live);tf=new RobotTf();tf.accept(new JSONArray().put(edge("base","wheel",1,false,0,0,0)).put(edge("camera","wheel",2,false,0,0,0)),100);assertFalse(tf.solve("base",links(),100).live);RobotTf bad=new RobotTf();JSONObject row=edge("base","wheel",1,false,0,0,0);row.put("rotation",new JSONArray().put(0).put(0).put(0).put(0));bad.accept(new JSONArray().put(row),100);assertFalse(bad.solve("base",new HashSet<>(Arrays.asList("base","wheel")),100).live);}

 @Test public void cycleThroughFixedFrameIsRejectedRatherThanHiddenByRootTermination()throws Exception{RobotTf tf=new RobotTf();tf.accept(new JSONArray().put(edge("base","wheel",10,false,1,0,0)).put(edge("wheel","camera",0,true,0,1,0)),100);assertTrue(tf.solve("base",links(),100).live);tf.accept(new JSONArray().put(edge("camera","base",0,true,0,0,0)),200);RobotTf.Pose p=tf.solve("base",links(),200);assertFalse("Cycle through fixed root must not be live",p.live);assertTrue(p.transforms.isEmpty());}
}
